"use client"

import * as React from "react"

import { cn } from "@/lib/utils"

type MaskedValueProps = Omit<React.ComponentProps<"span">, "children"> & {
  label: string
  value: string
  revealed?: boolean
  defaultRevealed?: boolean
  onRevealedChange?: (revealed: boolean) => void
  mask?: string
  revealLabel?: string
  hideLabel?: string
  buttonProps?: Omit<React.ComponentProps<"button">, "children" | "type" | "aria-expanded" | "aria-controls">
}

/** Screen privacy: closed, the reading isn't rendered. This is not storage or access control. */
function MaskedValue({ label, value, revealed: controlled, defaultRevealed = false, onRevealedChange, mask = "Not shown", revealLabel = "Reveal", hideLabel = "Hide", buttonProps, className, id, ...props }: MaskedValueProps) {
  const generated = React.useId()
  const valueId = `${id ?? generated}-value`
  const [open, setOpen] = React.useState(defaultRevealed)
  const revealed = controlled ?? open
  const [previous, setPrevious] = React.useState(revealed)
  const [acted, setActed] = React.useState(false)
  if (previous !== revealed) { setPrevious(revealed); setActed(true) }
  return <span {...props} id={id} data-slot="masked-value" data-revealed={revealed ? "" : undefined} data-acted={acted ? "" : undefined} className={cn("db-masked", className)}>
    <span data-slot="masked-value-label" className="db-masked-label">{label}</span>
    <span data-slot="masked-value-reading" id={valueId} className="db-masked-reading">{revealed ? <bdi className="db-yours db-reading">{value}</bdi> : mask}</span>
    <button {...buttonProps} type="button" data-slot="masked-value-trigger" className={cn("db-masked-trigger", buttonProps?.className)} aria-expanded={revealed} aria-controls={valueId} aria-label={buttonProps?.["aria-label"] ?? `${revealed ? hideLabel : revealLabel} ${label}`} onClick={(e) => {
      buttonProps?.onClick?.(e)
      if (e.defaultPrevented) return
      if (controlled === undefined) setOpen(!revealed)
      onRevealedChange?.(!revealed)
    }}>{revealed ? hideLabel : revealLabel}</button>
  </span>
}

export { MaskedValue, type MaskedValueProps }

@layer components {
  /* 20(25), enlarged: parentheses open a private reading, with no hidden copy left in the closed setting. */
  .db-masked { display: inline-grid; inline-size: 100%; grid-template-columns: minmax(0, 1fr) auto; align-items: end; column-gap: var(--db-space-4); row-gap: var(--db-space-5); max-inline-size: 100%; overflow-wrap: anywhere; }
  .db-masked-label { grid-column: 1 / -1; font-size: var(--db-pp); color: var(--db-graphite); }
  .db-masked-reading { position: relative; grid-column: 1 / -1; padding-inline: 0.65em; min-inline-size: 0; color: var(--db-pencil); font-family: var(--db-voice); font-style: normal; font-weight: 300; font-size: clamp(2rem, 5vw, 3.5rem); line-height: 1.2; letter-spacing: -0.035em; min-block-size: 2.6em; display: flex; align-items: center; }
  .db-masked-reading::before, .db-masked-reading::after { position: absolute; font-family: var(--db-voice); font-style: normal; font-weight: 200; font-size: 1.5em; color: var(--db-pencil); line-height: 1; inset-block-start: 50%; transform: translateY(-50%); transition: transform var(--db-andante) var(--db-spiccato), color var(--db-moderato); }
  .db-masked-reading::before { content: "(" / ""; inset-inline-start: 0; }
  .db-masked-reading::after { content: ")" / ""; inset-inline-end: 0; }
  .db-masked[data-revealed] .db-masked-reading { color: var(--db-ink); font-family: var(--db-expression); font-style: italic; }
  .db-masked[data-revealed] .db-masked-reading::before { transform: translateY(-50%) scaleY(1.25) rotate(-5deg); }
  .db-masked[data-revealed] .db-masked-reading::after { transform: translateY(-50%) scaleY(1.25) rotate(5deg); }
  .db-masked-reading bdi { font-size: 1em; line-height: 1.2; }
  .db-masked[data-acted][data-revealed] bdi { animation: db-masked-unfold var(--db-andante) var(--db-exhale); }
  .db-masked-trigger { grid-column: 2; border: 0; background: none; min-inline-size: 5rem; min-block-size: 44px; padding: var(--db-space-3) 0; font-size: var(--db-pp); cursor: pointer; text-decoration: underline; text-underline-offset: 0.35em; color: var(--db-graphite); text-align: end; }
  .db-masked-trigger:hover { color: var(--db-ink); }
  .db-masked-trigger:disabled { color: var(--db-pencil); cursor: default; }
  @keyframes db-masked-unfold { 0% { clip-path: inset(0 50%); transform: perspective(400px) rotateY(-15deg) skewX(-8deg); letter-spacing: 0.06em; } 60% { clip-path: inset(0); transform: perspective(400px) rotateY(2deg) skewX(1deg); } 100% { clip-path: inset(0); transform: none; letter-spacing: -0.035em; } }
  @media (prefers-reduced-motion: reduce) { .db-masked-reading::before, .db-masked-reading::after, .db-masked[data-revealed] bdi { transition: none; animation: none; } }
}
